head.script:
scwin.gridView2_oneditkeydown = function(info) {
    console.log("gridView2_oneditkeydown");
    console.log("info.rowIndex : " + info.rowIndex);
    console.log("info.colIndex : " + info.colIndex);
};
scwin.gridView2_onblankclick = function(e) {
    gridView2.setFocusedCell(0, 0, true);
};
scwin.div_Search_cal_ObjDt_onkeydown = function(e) {
    if (e.keyCode == '13') {
        div_Search_btn_Search.focus();
    }
};
scwin.div_Search_btn_Search_onclick = function(e) {
    var row = dst_tr01_out01.insertRow();
    gridView2.setFocusedCell(0, 0, true);
};
scwin.input11_onkeydown = function(e) {
    WebSquare.wUnit.getDomById('input2').focus();
};
scwin.input11_onkeypress = function(e) {
    if (e.keyCode == '13') {
        div_Search_btn_Search.focus();
    }
};
scwin.input11_oneditkeyup = function(info) {};
scwin.div_Search_cal_ObjDt_onkeyup = function(e) {
    if (e.keyCode == '13') {
        div_Search_btn_Search.focus();
    }
};
scwin.isFocus = function() {
    return WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById('G_'+$p.id+'gridView2__chk_col')).is(':focus');
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 버튼을 클릭한다.
    //1. Run the sample file and click the button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('div_Search_btn_Search').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 1. 첫번째 컬럼영역이 선택(주황색)되어진다.
    //1. The first column area is selected (orange).
    WebSquare.wUnit.addCommand("assert", "scwin.isFocus()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 그리드 영역내부(컬럼영역제외)에서 마우스를 이동하여 클릭한다.
    //2. Move the mouse inside the grid area (except for the column area) and click.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView2_dataLayer').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 2. 선택한 컬럼영역에 focus가 edit모드로 계속 보여진다.(이전에는 focus는 보여지지 않고 계속 선택영역으로 보여짐)
    //2. The focus is continuously displayed in edit mode in the selected column area (previously the focus is not shown but is still displayed as the selection area)
    WebSquare.wUnit.addCommand("assert", "scwin.isFocus()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 28-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
